1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #eceef1;
16	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
17	  }
18	  .calc {
19	    width: 320px;
20	    max-width: calc(100vw - 32px);
21	    background: #1f2227;
22	    border-radius: 20px;
23	    padding: 20px;
24	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
25	  }
26	  .display {
27	    color: #fff;
28	    font-size: 44px;
29	    text-align: right;
30	    padding: 16px 8px 20px;
31	    min-height: 88px;
32	    overflow-x: auto;
33	    white-space: nowrap;
34	  }
35	  .keys {
36	    display: grid;
37	    grid-template-columns: repeat(4, 1fr);
38	    gap: 10px;
39	  }
40	  button {
41	    font: inherit;
42	    font-size: 22px;
43	    height: 60px;
44	    border: none;
45	    border-radius: 12px;
46	    background: #3a3e45;
47	    color: #fff;
48	    cursor: pointer;
49	  }
50	  button:active { filter: brightness(1.25); }
51	  button.op { background: #f59e0b; }
52	  button.clear { background: #9ca3af; color: #111; }
53	  button.wide { grid-column: span 2; }
54	  .tape { margin-top: 16px; border-top: 1px solid #3a3e45; padding-top: 12px; }
55	  .tape-head { display: flex; justify-content: space-between; align-items: center; color: #9ca3af; font-size: 14px; }
56	  .tape-head button { font-size: 14px; height: 28px; padding: 0 12px; background: #3a3e45; }
57	  .tape-rows { max-height: 180px; overflow-y: auto; }
58	  .tape-row { display: flex; justify-content: space-between; gap: 12px; padding: 6px 0; font-size: 15px; }
59	  .tape-row + .tape-row { border-top: 1px solid #2c3036; }
60	  .tape-expr { color: #9ca3af; overflow-wrap: anywhere; }
61	  .tape-result { color: #fff; white-space: nowrap; }
62	</style>
63	</head>
64	<body>
65	<div class="calc">
66	  <div class="display" data-testid="calc-display" data-value="0" data-error="false">0</div>
67	  <div class="keys">
68	    <button class="clear wide" data-testid="key-lparen">(</button>
69	    <button class="clear wide" data-testid="key-rparen">)</button>
70	    <!-- [REQ-006] no % key; AC takes its space -->
71	    <button class="clear wide" data-testid="key-clear">AC</button>
72	    <button class="clear" data-testid="key-sign">±</button>
73	    <button class="op" data-testid="key-div" data-op="/">÷</button>
74	    <button data-testid="key-7" data-digit="7">7</button>
75	    <button data-testid="key-8" data-digit="8">8</button>
76	    <button data-testid="key-9" data-digit="9">9</button>
77	    <button class="op" data-testid="key-mul" data-op="*">×</button>
78	    <button data-testid="key-4" data-digit="4">4</button>
79	    <button data-testid="key-5" data-digit="5">5</button>
80	    <button data-testid="key-6" data-digit="6">6</button>
81	    <button class="op" data-testid="key-sub" data-op="-">−</button>
82	    <button data-testid="key-1" data-digit="1">1</button>
83	    <button data-testid="key-2" data-digit="2">2</button>
84	    <button data-testid="key-3" data-digit="3">3</button>
85	    <button class="op" data-testid="key-add" data-op="+">+</button>
86	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
87	    <button data-testid="key-dot">.</button>
88	    <button class="op" data-testid="key-equals">=</button>
89	  </div>
90	  <!-- [REQ-007] running tape of past calculations, newest first -->
91	  <div class="tape">
92	    <div class="tape-head">
93	      <span>History</span>
94	      <button data-testid="tape-clear">Clear</button>
95	    </div>
96	    <div class="tape-rows" data-testid="calc-tape"></div>
97	  </div>
98	</div>
99	<script>
100	  var displayEl = document.querySelector('[data-testid="calc-display"]');
101	  var tapeEl = document.querySelector('[data-testid="calc-tape"]');
102	  var OP_SYMBOLS = { '+': '+', '-': '−', '*': '×', '/': '÷' };
103	
104	  var state;
105	
106	  // [REQ-007] the entry as it reads in the expression: a closed group, or the number
107	  function entryText() {
108	    return state.entryExpr !== null ? state.entryExpr : formatNumber(Number(state.entry));
109	  }
110	
111	  // [REQ-007] add a tape row at the top; data-value holds String(value)
112	  function addTapeRow(expr, value) {
113	    var row = document.createElement('div');
114	    row.className = 'tape-row';
115	    row.setAttribute('data-testid', 'tape-row');
116	    var exprEl = document.createElement('span');
117	    exprEl.className = 'tape-expr';
118	    exprEl.setAttribute('data-testid', 'tape-expr');
119	    exprEl.textContent = expr;
120	    var resultEl = document.createElement('span');
121	    resultEl.className = 'tape-result';
122	    resultEl.setAttribute('data-testid', 'tape-result');
123	    resultEl.setAttribute('data-value', String(value));
124	    resultEl.textContent = formatNumber(value);
125	    row.appendChild(exprEl);
126	    row.appendChild(resultEl);
127	    tapeEl.insertBefore(row, tapeEl.firstChild);
128	  }
129	
130	  // [REQ-001] reset to the initial state: display 0, nothing pending
131	  // [REQ-003] clear also leaves the error state
132	  function clearAll() {
133	    state = { entry: '0', stored: null, op: null, fresh: true, typing: false, error: false, groups: [],
134	      tokens: [], entryExpr: null };
135	    render();
136	  }
137	
138	  // [REQ-001] apply an operator
139	  // [REQ-003] exact result, never rounded; division by zero returns null (error)
140	  function compute(a, op, b) {
141	    if (op === '+') return a + b;
142	    if (op === '-') return a - b;
143	    if (op === '*') return a * b;
144	    if (b === 0) return null;
145	    return a / b;
146	  }
147	
148	  // [REQ-003] presentation only: at most 10 significant digits, no trailing zeros,
149	  // exponential only when |n| >= 1e10 or |n| < 1e-9
150	  function formatNumber(n) {
151	    if (n === 0) return '0';
152	    if (!isFinite(n)) return String(n);
153	    var parts = n.toExponential(9).split('e');
154	    var exp = Number(parts[1]);
155	    if (exp >= 10 || exp < -9) {
156	      return parts[0].replace(/\.?0+$/, '') + 'e' + (exp >= 0 ? '+' : '') + exp;
157	    }
158	    var sign = n < 0 ? '-' : '';
159	    var digits = parts[0].replace('-', '').replace('.', '');
160	    var intPart, fracPart;
161	    if (exp >= 0) {
162	      intPart = digits.slice(0, exp + 1);
163	      fracPart = digits.slice(exp + 1);
164	    } else {
165	      intPart = '0';
166	      fracPart = new Array(-exp).join('0') + digits;
167	    }
168	    fracPart = fracPart.replace(/0+$/, '');
169	    return sign + intPart + (fracPart ? '.' + fracPart : '');
170	  }
171	
172	  // [REQ-003] enter the error state
173	  function setError() {
174	    state.error = true;
175	    render();
176	  }
177	
178	  // [REQ-001] digits build the entry
179	  // [REQ-004] a shown result (not typed) is replaced, not appended to
180	  // [REQ-007] a new number replaces a closed group in the expression
181	  function inputDigit(d) {
182	    state.entryExpr = null;
183	    if (state.fresh || !state.typing) {
184	      state.entry = d;
185	      state.fresh = false;
186	    } else {
187	      state.entry = state.entry === '0' ? d : state.entry + d;
188	    }
189	    state.typing = true;
190	    render();
191	  }
192	
193	  // [REQ-001] at most one decimal point per entry
194	  function inputDot() {
195	    state.entryExpr = null; // [REQ-007]
196	    if (state.fresh || !state.typing) {
197	      state.entry = '0.';
198	      state.fresh = false;
199	    } else if (state.entry.indexOf('.') === -1) {
200	      state.entry += '.';
201	    }
202	    state.typing = true;
203	    render();
204	  }
205	
206	  // [REQ-004] flip the sign of the current entry; a typed entry keeps its text
207	  // [REQ-007] flipping a closed group marks the group with −
208	  function inputSign() {
209	    if (state.entryExpr !== null) {
210	      state.entryExpr = state.entryExpr.charAt(0) === '−' ? state.entryExpr.slice(1) : '−' + state.entryExpr;
211	    }
212	    if (state.typing) {
213	      if (state.entry !== '0') {
214	        state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
215	      }
216	    } else {
217	      state.entry = String(-Number(state.entry) || 0);
218	      state.fresh = false;
219	    }
220	    render();
221	  }
222	
223	  // [REQ-001] store the operator; chains evaluate left to right
224	  // [REQ-002] immediate execution: an operator first applies the waiting op and shows the
225	  // running result; no precedence, so 2 + 3 × 4 = is 20
226	  // [REQ-007] record the entry and operator; a replaced operator replaces its token
227	  function inputOp(op) {
228	    var current = Number(state.entry);
229	    if (state.fresh && state.op !== null) {
230	      state.tokens[state.tokens.length - 1] = OP_SYMBOLS[op];
231	    } else {
232	      state.tokens.push(entryText(), OP_SYMBOLS[op]);
233	    }
234	    state.entryExpr = null;
235	    if (state.op !== null && !state.fresh) {
236	      var result = compute(state.stored, state.op, current);
237	      if (result === null) return setError();
238	      state.entry = String(result);
239	      state.stored = result;
240	    } else if (state.op === null) {
241	      state.stored = current;
242	    }
243	    state.op = op;
244	    state.fresh = true;
245	    state.typing = false;
246	    render();
247	  }
248	
249	  // [REQ-005] open a group: park the waiting stored value and op; the group starts empty
250	  // [REQ-007] the group remembers where its tokens start
251	  function openGroup() {
252	    state.groups.push({ stored: state.op === null ? null : state.stored, op: state.op, at: state.tokens.length });
253	    state.tokens.push('(');
254	    state.entryExpr = null;
255	    state.stored = null;
256	    state.op = null;
257	    state.fresh = true;
258	    state.typing = false;
259	    render();
260	  }
261	
262	  // [REQ-005] close the innermost group: its result becomes the entry for the outer op
263	  function closeGroup() {
264	    if (state.groups.length === 0) return;
265	    var value = Number(state.entry);
266	    if (state.op !== null) {
267	      value = compute(state.stored, state.op, value);
268	      if (value === null) return setError();
269	    }
270	    var outer = state.groups.pop();
271	    // [REQ-007] the whole group becomes the entry's text
272	    state.entryExpr = state.tokens.splice(outer.at).concat(entryText(), ')').join(' ');
273	    state.stored = outer.stored;
274	    state.op = outer.op;
275	    state.entry = String(value);
276	    state.fresh = false;
277	    state.typing = false;
278	    render();
279	  }
280	
281	  // [REQ-001] equals shows the result of stored op entry
282	  // [REQ-005] equals first closes any open groups
283	  // [REQ-007] a completed calculation adds a tape row
284	  function equals() {
285	    var closed = state.groups.length > 0;
286	    while (state.groups.length > 0) {
287	      closeGroup();
288	      if (state.error) return;
289	    }
290	    if (state.op === null) {
291	      if (closed) {
292	        addTapeRow(state.tokens.concat(entryText()).join(' '), Number(state.entry));
293	        state.tokens = [];
294	        state.entryExpr = null;
295	      }
296	      return;
297	    }
298	    var result = compute(state.stored, state.op, Number(state.entry));
299	    if (result === null) return setError();
300	    addTapeRow(state.tokens.concat(entryText()).join(' '), result);
301	    state.tokens = [];
302	    state.entryExpr = null;
303	    state.entry = String(result);
304	    state.stored = null;
305	    state.op = null;
306	    state.fresh = true;
307	    state.typing = false;
308	    render();
309	  }
310	
311	  // [REQ-001] data-value holds String(value)
312	  // [REQ-003] typed entry shown as typed; other numbers formatted at render time only;
313	  // data-value stays exact; data-error always present
314	  function render() {
315	    var value = Number(state.entry);
316	    if (state.error) {
317	      displayEl.textContent = 'Error';
318	      displayEl.setAttribute('data-value', 'NaN');
319	    } else {
320	      displayEl.textContent = state.typing ? state.entry : formatNumber(value);
321	      displayEl.setAttribute('data-value', String(value));
322	    }
323	    displayEl.setAttribute('data-error', state.error ? 'true' : 'false');
324	  }
325	
326	  document.querySelector('.keys').addEventListener('click', function (e) {
327	    var btn = e.target.closest('button');
328	    if (!btn) return;
329	    var id = btn.getAttribute('data-testid');
330	    // [REQ-003] in the error state only clear works
331	    if (state.error && id !== 'key-clear') return;
332	    if (btn.hasAttribute('data-digit')) inputDigit(btn.getAttribute('data-digit'));
333	    else if (btn.hasAttribute('data-op')) inputOp(btn.getAttribute('data-op'));
334	    else if (id === 'key-dot') inputDot();
335	    else if (id === 'key-equals') equals();
336	    else if (id === 'key-sign') inputSign();
337	    else if (id === 'key-lparen') openGroup();
338	    else if (id === 'key-rparen') closeGroup();
339	    else if (id === 'key-clear') clearAll();
340	  });
341	
342	  // [REQ-007] clearing the tape leaves the calculator and display alone
343	  document.querySelector('[data-testid="tape-clear"]').addEventListener('click', function () {
344	    tapeEl.textContent = '';
345	  });
346	
347	  clearAll();
348	</script>
349	</body>
350	</html>
